import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { FiUser, FiPhone, FiLock, FiUserCheck } from 'react-icons/fi';

const Register = () => {
    const [name, setName] = useState('');
    const [phone, setPhone] = useState('');
    const [password, setPassword] = useState('');
    const [confirm, setConfirm] = useState('');
    const [userType, setUserType] = useState('comprador');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const { register } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        if (password !== confirm) { setError('Senhas não coincidem'); return; }
        if (password.length < 6) { setError('Senha deve ter 6+ caracteres'); return; }
        setLoading(true);
        const result = await register(name, phone, password, userType);
        if (result.success) navigate(userType === 'vendedor' ? '/seller/dashboard' : '/');
        setLoading(false);
    };

    return (
        <div className="max-w-md mx-auto">
            <div className="bg-white rounded-xl shadow-md p-8">
                <h2 className="text-2xl font-bold text-center mb-6">Criar conta</h2>
                {error && <div className="bg-red-50 text-red-600 p-3 rounded-lg mb-4">{error}</div>}
                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-gray-700 mb-2">Nome *</label>
                        <div className="relative">
                            <FiUser className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                            <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Seu nome" className="w-full pl-10 pr-3 py-2 border rounded-lg" required />
                        </div>
                    </div>
                    <div className="mb-4">
                        <label className="block text-gray-700 mb-2">Telefone *</label>
                        <div className="relative">
                            <FiPhone className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                            <input type="tel" value={phone} onChange={e => setPhone(e.target.value)} placeholder="923456789" className="w-full pl-10 pr-3 py-2 border rounded-lg" required />
                        </div>
                    </div>
                    <div className="mb-4">
                        <label className="block text-gray-700 mb-2">Senha *</label>
                        <div className="relative">
                            <FiLock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                            <input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Mínimo 6 caracteres" className="w-full pl-10 pr-3 py-2 border rounded-lg" required />
                        </div>
                    </div>
                    <div className="mb-4">
                        <label className="block text-gray-700 mb-2">Confirmar senha *</label>
                        <div className="relative">
                            <FiLock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                            <input type="password" value={confirm} onChange={e => setConfirm(e.target.value)} placeholder="Digite novamente" className="w-full pl-10 pr-3 py-2 border rounded-lg" required />
                        </div>
                    </div>
                    <div className="mb-6">
                        <label className="block text-gray-700 mb-2">Tipo de conta</label>
                        <div className="grid grid-cols-2 gap-4">
                            <button type="button" onClick={() => setUserType('comprador')} className={`py-2 rounded-lg border ${userType === 'comprador' ? 'bg-primary-600 text-white' : 'border-gray-300'}`}>Comprador</button>
                            <button type="button" onClick={() => setUserType('vendedor')} className={`py-2 rounded-lg border ${userType === 'vendedor' ? 'bg-primary-600 text-white' : 'border-gray-300'}`}>Vendedor</button>
                        </div>
                    </div>
                    <button type="submit" disabled={loading} className="w-full bg-primary-600 text-white py-2 rounded-lg hover:bg-primary-700">{loading ? 'Cadastrando...' : 'Cadastrar'}</button>
                </form>
                <p className="text-center mt-4">Já tem conta? <Link to="/login" className="text-primary-600">Faça login</Link></p>
            </div>
        </div>
    );
};

export default Register;
